_id": "8b294946-a8df-53bc-8489-86858983f268", "scoring_reasons": [{"method": "manual_source_and_identity_review", "reason": "官方裁判的具體公職／選舉身分敘事，與本機 canonical 人物的歷史職務與地區可交叉確認。", "reviewedAt": "2026-09-21T09:38:13.445306+00:00", "identityEvidence": "本機 canonical person cf7d723a-1e21-4897-bcf2-324c32f63012 的人物快照為宜蘭縣議員（宜蘭縣第6選舉區）；官方裁判載明「尤有甚者，被告余永川為被告陳漢鍾之表兄，依被告余永川以證人身分具結所為之證述：伊是於97年4、5月間在被告陳漢鍾之服務處認識被告黃金謀、許育甄夫妻，因為被告陳漢鍾不在，所以帶被告黃金謀、許育甄前往其住處喝茶聊天，被告黃金謀表示要向伊承租房屋做宿舍，沒有提到租金多少，被告黃金謀僅表示如果有賺錢會包紅包給伊等情（第34卷第220-222頁），而該時，正係被告黃金謀、許育甄、林東權、林柏盛等人商討籌設偽造美鈔工廠之初始，衡情從事犯罪行為勢必掩人耳目、小心為之，更何況被告余永川係當地鎮民代表主席即被告陳漢鍾之表哥，以被告陳漢鍾鎮民代表主席之身分，其在地方之力量亦不容小覷，是若無被告陳漢鍾之指示，被告黃…」。"}], "auto_reviewed_at": "2026-09-21T09:38:13.445306+00:00", "scoring_version": "council2026-manual-continued-v2", "review_score": 100}, {"id": "149507af-fe5d-50c1-bb51-7274660fe13e", "claim_key": "council2026:legal-pending:b495cdc309c6571e992d9748", "is_public": true, "person_id": "7fd666f2-3ef8-4732-ad57-7d5f7b233d8b", "claim_json": {"finality": {"basis": "有罪確定", "status": "historical_judgment_verified", "isFinal": null}, "sourceId": "council2026-public-research", "caseStage": "criminal_judgment", "recordType": "criminal", "safetyFlags": ["current_outcome_not_independently_verified"], "judgmentDate": "2012-01-31", "evidenceSources": [{"url": "https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=ULDM%2C100%2C%E7%B0%A1%E4%B8%8A%2C108%2C20120131%2C1", "name": "司法院裁判書系統", "tier": "official", "supports": "本筆主張的裁判或人物身分依據"}, {"url": "https://tw.news.yahoo.com/%E5%A4%AB%E5%A6%BB%E6%AA%94%E8%81%AF%E5%90%88%E7%AB%B6%E7%B8%BD%E6%88%90%E7%AB%8B-%E8%94%A1%E5%92%8F%E9%8D%80%E6%9C%89%E6%84%8F%E5%95%8F%E9%BC%8E%E5%89%AF%E8%AD%B0%E9%95%B7-095838167.html", "name": "司法院裁判書系統", "tier": "independent_public_source", "supports": "本筆主張的裁判或人物身分依據"}, {"url": "https://civil.yunlin.gov.tw/News_Content.aspx?n=11818&s=548715", "name": "司法院裁判書系統", "tier": "independent_public_source", "supports": "本筆主張的裁判或人物身分依據"}], "publicationGate": {"status": "published", "approvedA