ce_level": "A", "source_person_id": "e226695b-151c-54f9-8d7d-b7e8e3c9540f", "scoring_reasons": [{"method": "manual_source_and_identity_review", "reason": "官方裁判的具體公職／選舉身分敘事，與本機 canonical 人物的歷史職務與地區可交叉確認。", "reviewedAt": "2026-09-21T09:38:13.445306+00:00", "identityEvidence": "本機 canonical person af8d759a-1b06-408b-9db9-d0c2d0880ea7 的人物快照為高雄市議員（高雄市第10選舉區）；官方裁判載明「事實一、陳麗娜係中國國民黨籍，為中央選舉委員會公告高雄縣、市合併後第一屆高雄市市議員選舉第十選區之當選人，於民國99年12月25日上午9時許，與全體市議員當選人集體至高雄市議會報到後宣誓就職，而取得公務員身分，並隨即於同日9時30分許舉行高雄市議會議長、副議長選舉，而選舉前同黨籍之同屆市議員當選人許崑源已表態參選議長選舉，許崑源並曾尋求陳麗娜之支持，陸淑美雖未表態與許崑源搭檔參選副議長選舉，惟投票當日因陸淑美曾經擔任副議長，因此取得國民黨籍市議員當選人之共識決定支持，民主進步黨則推舉同屆市議員康裕成、蔡昌達搭檔參選議長、副議長，於當日選舉前並由當選之市議員互推黃石龍、許崑源、黃柏霖、林武忠、張…」。"}], "auto_reviewed_at": "2026-09-21T09:38:13.445306+00:00", "scoring_version": "council2026-manual-continued-v2", "review_score": 100}, {"id": "bc36512f-3da9-5783-80c6-ba450ed8fc98", "claim_key": "council2026:legal-pending:4f2add392cd88da18a1602ba", "is_public": true, "person_id": "f8464c11-baa3-4f40-a07d-e3d7a09b80af", "claim_json": {"finality": {"basis": "已確定", "status": "historical_judgment_verified", "isFinal": null}, "sourceId": "council2026-public-research", "caseStage": "criminal_judgment", "recordType": "criminal", "safetyFlags": ["current_outcome_not_independently_verified"], "judgmentDate": "2025-05-15", "evidenceSources": [{"url": "https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TPHM%2C114%2C%E4%B8%8A%E6%98%93%2C7%2C20250515%2C1", "name": "司法院裁判書系統", "tier": "official", "supports": "本筆主張的裁判或人物身分依據"}, {"url": "https://udn.com/vote2026/story/124652/9409570", "name": "司法院裁判書系統", "tier": "independent_public_source", "supports": "本筆主張的裁判或人物身分依據"}, {"url": "https://web.cec.gov.tw/api/file/9cdda387-4bb9-4939-8825-1d1a8cd66684.pdf", "name": "司法院裁判書系統", "tier": "independent_public_source", "supports": "本筆主張的裁判或人物身分依據"}], "publicationGate": {"status": "published", "approvedAt": "2026-09-22T11:48:08.373572+00:00", "approvedBy": "project_owner", "approvalScope": "production_release_pr52_exact_42_claims",