DO $$ BEGIN
IF (SELECT count(DISTINCT id) FROM release_sources)<>39 OR (SELECT count(DISTINCT source_person_key) FROM release_sources)<>39 OR (SELECT count(DISTINCT id) FROM release_claims)<>42 THEN RAISE EXCEPTION 'Duplicate release identity'; END IF;
IF EXISTS(SELECT 1 FROM release_sources WHERE is_public IS DISTINCT FROM FALSE OR source_payload IS DISTINCT FROM '{}'::jsonb) THEN RAISE EXCEPTION 'Private source projection drift'; END IF;
IF EXISTS(SELECT 1 FROM release_claims c LEFT JOIN release_sources s ON s.id=c.source_person_id WHERE s.id IS NULL OR c.source_url NOT LIKE 'https://%' OR c.claim_json->'publicationGate'->>'approvalScope' IS DISTINCT FROM 'production_release_pr52_exact_42_claims') THEN RAISE EXCEPTION 'Provenance or approval mismatch'; END IF;
IF (SELECT count(*) FROM release_sources)<>39 OR (SELECT count(*) FROM release_claims)<>42 THEN RAISE EXCEPTION 'Release count mismatch'; END IF;
IF EXISTS(SELECT 1 FROM release_claims c LEFT JOIN public.people p ON p.id=c.person_id WHERE p.id IS NULL OR p.is_public IS DISTINCT FROM TRUE) THEN RAISE EXCEPTION 'Published person missing'; END IF;
IF NOT EXISTS(SELECT 1 FROM public.people WHERE id='f8464c11-baa3-4f40-a07d-e3d7a09b80af' AND name='張靜' AND external_id='cec-2024-party-list-person-68ea09b890fc7b04' AND source_url='https://2024.cec.gov.tw/data/json/cand/L4/00000.json') THEN RAISE EXCEPTION 'Canonical identity changed'; END IF;
IF EXISTS(SELECT 1 FROM release_claims r JOIN public.person_claims c ON c.id=r.id OR c.claim_key=r.claim_key) THEN RAISE EXCEPTION 'Claims already exist: reconcile, do not overwrite'; END IF;
IF EXISTS(SELECT 1 FROM release_sources r JOIN public.source_people s ON s.id=r.id OR s.source_person_key=r.source_person_key) THEN RAISE EXCEPTION 'Sources already exist: reconcile, do not overwrite'; END IF;
END $$;

INSERT INTO public.source_people ("id","source_person_key","source_type","source_id","source_name","source_url","raw_name","normalized_name","external_person_id","external_record_id","is_public","source_payload") SELECT "id","source_person_key","source_type","source_id","source_name","source_url","raw_name","normalized_name","external_person_id","external_record_id","is_public","source_payload" FROM release_sources;

INSERT INTO public.person_claims ("id","claim_key","is_public","person_id","claim_json","claim_type","created_at","source_url","updated_at","visibility","claim_value","observed_at","source_name","candidate_id","review_status","confidence_level","source_person_id","scoring_reasons","auto_reviewed_at","scoring_version","review_score") SELECT "id","claim_key","is_public","person_id","claim_json","claim_type","created_at","source_url","updated_at","visibility","claim_value","observed_at","source_name","candidate_id","review_status","confidence_level","source_person_id","scoring_reasons","auto_reviewed_at","scoring_version","review_score" FROM release_claims;


-- Release the 41 reviewed legacy legal-case backfills plus the separately
-- reviewed specified appeal case. The six blocked legacy cases are intentionally
-- excluded. This migration only adds judgmentDisposition to the existing JSON.

CREATE TEMP TABLE _reviewed_legal_disposition_release (
  claim_id uuid PRIMARY KEY,
  claim_key text NOT NULL,
  person_id uuid NOT NULL,
  source_url text NOT NULL,
  review_status text NOT NULL,
  visibility text NOT NULL,
  is_public boolean NOT NULL,
  disposition jsonb NOT NULL
) ON COMMIT DROP;

