  ('bdb011ce-c6a6-557a-8257-a453f9dd52c4', 'council2026:legal-pending:c4c9501d7567dc600785890f', '6daac75e-813f-4114-a5ff-9d1a97fc68cf', 'https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=SCDM%2C112%2C%E8%A8%B4%2C578%2C20250430%2C2', 'verified', 'public', TRUE, '{"text":"黃文政犯利用職務機會詐取財物罪，共貳罪，各處有期徒刑壹年捌月，各褫奪公權貳年。應執行有期徒刑貳年，褫奪公權貳年。緩刑伍年，並應於本案判決確定後壹年內，向公庫支付新臺幣參拾萬元。","result":"guilty","section":"主文","version":1,"personId":"6daac75e-813f-4114-a5ff-9d1a97fc68cf","sourceUrl":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=SCDM%2C112%2C%E8%A8%B4%2C578%2C20250430%2C2","caseNumber":"臺灣新竹地方法院112年度訴字第578號","judgmentDate":"2025-04-30","reviewStatus":"reviewed"}'::jsonb),
