  ('f80e53d2-3604-559f-8019-20f0c93e7370', 'council2026:legal-pending:23f534086bad10265a5b0936', '9a4dd4cc-8636-4060-b494-4df5380a49c3', 'https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TPHM%2c114%2c%e4%b8%8a%e8%a8%b4%2c2282%2c20260903%2c4', 'verified', 'public', TRUE, '{"text":"其他（邱垂益、馬兆玲、邱烽堯部分，及呂禮旺之刑部分，暨黃越勝沒收部分）上訴駁回。","result":"unknown","section":"主文","version":2,"personId":"9a4dd4cc-8636-4060-b494-4df5380a49c3","sourceUrl":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TPHM%2c114%2c%e4%b8%8a%e8%a8%b4%2c2282%2c20260903%2c4","caseNumber":"臺灣高等法院114年度上訴字第2282號","judgmentDate":"2026-09-03","reviewStatus":"reviewed","upheldJudgment":{"prior":{"text":"邱烽堯與公務員共同犯對主管事務圖利罪，處有期徒刑3年6月。褫奪公權3年。","result":"guilty","section":"主文","version":1,"personId":"9a4dd4cc-8636-4060-b494-4df5380a49c3","sourceUrl":"https://www.judicial.gov.tw/tw/cp-1888-1147989-e29c3-1.html","caseNumber":"臺灣新北地方法院111年度訴字第796號","sourceKind":"court_published_main_text","judgmentDate":"2024-08-20","reviewStatus":"reviewed"},"scope":"entire_person_disposition","personId":"9a4dd4cc-8636-4060-b494-4df5380a49c3","relation":"appeal_dismissed","evidenceText":"不服臺灣新北地方法院111年度訴字第796號，中華民國113年8月20日第一審判決","reviewStatus":"reviewed","priorCaseNumber":"臺灣新北地方法院111年度訴字第796號","currentSourceUrl":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TPHM%2c114%2c%e4%b8%8a%e8%a8%b4%2c2282%2c20260903%2c4","personScopeQuote":"邱烽堯部分","currentCaseNumber":"臺灣高等法院114年度上訴字第2282號","evidenceSourceUrl":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TPHM%2c114%2c%e4%b8%8a%e8%a8%b4%2c2282%2c20260903%2c4","currentDispositionText":"其他（邱垂益、馬兆玲、邱烽堯部分，及呂禮旺之刑部分，暨黃越勝沒收部分）上訴駁回。"},"personScopeQuote":"邱烽堯部分"}'::jsonb);

DO $$
BEGIN
  IF (SELECT count(*) FROM _reviewed_legal_disposition_release) <> 42 THEN
    RAISE EXCEPTION 'Expected 42 reviewed legal judgment dispositions';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM _reviewed_legal_disposition_release AS release
    LEFT JOIN public.person_claims AS claim ON claim.id = release.claim_id
    WHERE claim.id IS NULL
       OR claim.claim_key IS DISTINCT FROM release.claim_key
       OR claim.person_id IS DISTINCT FROM release.person_id
       OR claim.claim_type IS DISTINCT FROM 'legal_case'
       OR claim.source_url IS DISTINCT FROM release.source_url
       OR claim.review_status IS DISTINCT FROM release.review_status
       OR claim.visibility IS DISTINCT FROM release.visibility
       OR claim.is_public IS DISTINCT FROM release.is_public
  ) THEN
    RAISE EXCEPTION 'Legal claim identity or protected release state has drifted';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM _reviewed_legal_disposition_release AS release
    JOIN public.person_claims AS claim ON claim.id = release.claim_id
    WHERE claim.claim_json ? 'judgmentDisposition'
      AND claim.claim_json -> 'judgmentDisposition' IS DISTINCT FROM release.disposition
  ) THEN
    RAISE EXCEPTION 'Existing judgmentDisposition conflicts with reviewed release data';
  END IF;
END
$$;

UPDATE public.person_claims AS claim
SET claim_json = jsonb_set(
      COALESCE(claim.claim_json, '{}'::jsonb),
      '{judgmentDisposition}',
      release.disposition,
      TRUE
    ),
    updated_at = now()
FROM _reviewed_legal_disposition_release AS release
WHERE claim.id = release.claim_id
  AND NOT (claim.claim_json ? 'judgmentDisposition');

DO $$
BEGIN
  IF (
    SELECT count(*)
    FROM _reviewed_legal_disposition_release AS release
    JOIN public.person_claims AS claim ON claim.id = release.claim_id
    WHERE claim.claim_json -> 'judgmentDisposition' = release.disposition
  ) <> 42 THEN
    RAISE EXCEPTION 'Reviewed legal judgment disposition release is incomplete';
  END IF;
END
$$;


DO $$ BEGIN
IF (SELECT count(*) FROM release_claims r JOIN public.person_claims c ON c.id=r.id WHERE c.claim_value IS NOT DISTINCT FROM r.claim_value AND c.claim_key=r.claim_key AND c.person_id=r.person_id AND c.source_person_id=r.source_person_id AND c.source_url=r.source_url AND c.review_status=r.review_status AND c.is_public AND (c.claim_json-'judgmentDisposition')=r.claim_json)<>42 THEN RAISE EXCEPTION 'Original claim readback failed'; END IF;
IF (SELECT count(*) FROM release_claims r JOIN published.person_claims c ON c.claim_id=r.id)<>42 THEN RAISE EXCEPTION 'Public claim projection incomplete'; END IF;
END $$;
COMMIT;
